def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    mod = 1_000_000_007
    size = len(alphabet)
    char_index = {char: i for i, char in enumerate(alphabet)}

    transitions = [[-1] * size]
    terminal = [False]

    for word in banned:
        state = 0
        for char in word:
            c = char_index[char]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * size)
                terminal.append(False)
            state = transitions[state][c]
        terminal[state] = True

    failure = [0] * len(transitions)
    queue = deque()

    for c in range(size):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]

        for c in range(size):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[failure[state]][c]
            else:
                failure[child] = transitions[failure[state]][c]
                queue.append(child)

    good_states = [state for state in range(len(transitions)) if not terminal[state]]
    index = {state: i for i, state in enumerate(good_states)}
    m = len(good_states)

    matrix = [[0] * m for _ in range(m)]
    for state in good_states:
        row = matrix[index[state]]
        for target in transitions[state]:
            if not terminal[target]:
                row[index[target]] += 1

    vector = [0] * m
    vector[index[0]] = 1

    while n:
        if n & 1:
            result = [0] * m
            for i, value in enumerate(vector):
                if value:
                    for j, weight in enumerate(matrix[i]):
                        result[j] += value * weight
            vector = [value % mod for value in result]

        n >>= 1
        if n:
            squared = [[0] * m for _ in range(m)]
            for i in range(m):
                row = squared[i]
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, weight in enumerate(matrix[k]):
                            row[j] += value * weight
                for j in range(m):
                    row[j] %= mod
            matrix = squared

    return sum(vector) % mod
